const createTeacher = async (teacherData, uid) => {
  const teacherDoc = {
    ...teacherData,
    ownerUid: uid,
    createdAt: admin.firestore.FieldValue.serverTimestamp(),
    status: 'active',
    lastActiveAt: admin.firestore.FieldValue.serverTimestamp()
  };

  const docRef = await admin.firestore().collection('teachers').add(teacherDoc);
  return docRef.id;
};

