};

const updateNetworkStats = async (teacherData) => {
  const statsRef = admin.firestore().collection('network_stats').doc('global');

  await admin.firestore().runTransaction(async (transaction) => {
    const statsDoc = await transaction.get(statsRef);
    const stats = statsDoc.data() || {};

    transaction.update(statsRef, {
      totalTeachers: (stats.totalTeachers || 0) + 1,
      gradesCovered: [...new Set([...stats.gradesCovered || [], ...teacherData.grades])],
      locationsCovered: [...new Set([...stats.locationsCovered || [], teacherData.location])]
    });
  });
};

